using System;using System.IO;using System.Collections.Generic;using System.Reflection;using UnityEditor;using UnityEngine;using FlyEditor.Flight;
namespace FlyEditor.Editor {
public static class ConnectedFoldVerification {
 static readonly BindingFlags Hidden=BindingFlags.NonPublic|BindingFlags.Instance;
 static void Check(bool v,string msg){if(!v)throw new Exception("[ConnectedFold] "+msg);}
 static PaperSheet.Face Face(Vector2[] points,PaperSheet.Face f,Matrix4x4 world)=> (PaperSheet.Face)Activator.CreateInstance(typeof(PaperSheet.Face),Hidden,null,new object[]{points,f.layer,f.back,world*f.frame,f.material},null);
 static PaperSheet Mesh(PaperSheet s,int rotate,bool split){var faces=new List<PaperSheet.Face>();var world=Matrix4x4.Rotate(Quaternion.Euler(0,rotate*90,0));foreach(var f in s.Faces){if(!split){faces.Add(Face(f.points,f,world));continue;}Vector2 c=Vector2.zero;foreach(var v in f.points)c+=v;c/=f.points.Length;for(int i=0;i<f.points.Length;i++)faces.Add(Face(new[]{f.points[i],f.points[(i+1)%f.points.Length],c},f,world));}return (PaperSheet)Activator.CreateInstance(typeof(PaperSheet),Hidden,null,new object[]{s.Format,s.Width,faces},null);}
 static Vector2 Local(PaperSheet.Face f,Vector3 m){var p=f.material.inverse.MultiplyPoint3x4(m);return new Vector2(p.x,p.z);}
 static FoldStep Locate(PaperSheet original,PaperSheet changed,FoldStep step,bool swap){var basis=original.Faces[step.anchor];Vector3 M(Vector2 p)=>basis.material.MultiplyPoint3x4(new Vector3(p.x,0,p.y));var t=M(step.pullTip);var h=M(step.pullStop);var l=M(swap?step.pullRight:step.pullLeft);var r=M(swap?step.pullLeft:step.pullRight);for(int i=0;i<changed.Faces.Count;i++){var f=changed.Faces[i];if(!f.Contains(Local(f,t)))continue;var candidate=step;candidate.anchor=i;candidate.flap=i+1;candidate.pullTip=Local(f,t);candidate.pullStop=Local(f,h);candidate.pullLeft=Local(f,l);candidate.pullRight=Local(f,r);candidate.connectedPetalBacking=true;var p=PaperCornerPull.Create(changed,candidate);if(p!=null&&p.UsesPetalFold)return candidate;}throw new Exception("[ConnectedFold] No fragmented petal plan");}
 static void SameGeometry(IReadOnlyList<PaperSheet.Face> expected,IReadOnlyList<PaperSheet.Face> actual){foreach(var f in actual)foreach(var p in f.points){var m=f.material.MultiplyPoint3x4(new Vector3(p.x,0,p.y));bool found=false;foreach(var g in expected){var q=Local(g,m);if(!g.Contains(q))continue;Check(Vector3.Distance(f.World(p,0),g.World(q,0))<.002f,"tessellation changed motion");found=true;}Check(found,"lost material point");}}
 [MenuItem("Tools/FlyEditor/Validation/Connected fragments and opening")]
 public static void Run(){var folder=Environment.GetEnvironmentVariable("FLYEDITOR_LILY")??Path.GetFullPath(Path.Combine(Application.dataPath,"../../Docs/OrigamiAudit/lily-study"));var recipe=JsonUtility.FromJson<ResearchSave>(File.ReadAllText(Path.Combine(folder,"partial.json"))).paperFolds;var step=recipe[15];Array.Resize(ref recipe,15);var source=PaperSheet.Replay(recipe);Check(source.Count==15,"source recipe");int poses=0;
 for(int rotation=0;rotation<4;rotation++)foreach(bool swap in new[]{false,true}){var whole=Mesh(source,rotation,false);var divided=Mesh(source,rotation,true);var originalStep=Locate(source,whole,step,swap);var fragmentedStep=Locate(source,divided,step,swap);var a=PaperCornerPull.Create(whole,originalStep);var b=PaperCornerPull.Create(divided,fragmentedStep);for(int angle=0;angle<=180;angle+=15){Check(a.Pose(-angle)&&b.Pose(-angle),"fragmented sweep "+angle);ReverseDirectionVerification.Geometry(b.Preview);SameGeometry(a.Preview,b.Preview);poses++;}foreach(int angle in new[]{90,15,150,0,180}){Check(b.Pose(-angle),"backward scrub");ReverseDirectionVerification.Geometry(b.Preview);}Check(!b.Pose(1),"stationary overlying layer was ignored");}
 var savedStep=Locate(source,source,step,false);var before=source.Faces;var plan=PaperCornerPull.Create(source,savedStep);Check(source.FinishPull(plan,-90),"partial commit");PetalFoldingVerification.Replay(source);Check(source.Undo()&&ReferenceEquals(before,source.Faces),"partial undo");plan=PaperCornerPull.Create(source,savedStep);Check(source.FinishPull(plan,-180),"full commit");PetalFoldingVerification.Replay(source);Check(source.Undo()&&ReferenceEquals(before,source.Faces),"full undo");
 int openings=0;foreach(float start in new[]{-150f,-90f,-45f,45f,90f,150f,180f})for(int r=0;r<4;r++){var s=new PaperSheet();var n=(r%2==0?Vector2.right:Vector2.up)*(r<2?1:-1);Check(s.ApplyStep(new FoldStep{creaseNormal=n,creaseOffset=Vector2.Dot(n,Vector2.one*5.5f),side=1,degrees=start,continuousHinge=true,neutralContacts=true,compactLayers=true}),"initial hinge");var faces=s.Faces;bool done=false;for(int i=0;i<faces.Count&&!done;i++)foreach(var v in faces[i].points){var turns=new List<PaperSheet.Turn>();s.OpeningTurns(new PaperSheet.FoldVertex(i,v),turns,false,true);foreach(var turn in turns){float degrees=turn.Constrain(30);if(degrees<10)degrees=turn.Constrain(-30);if(Mathf.Abs(degrees)<10)continue;Check(s.Finish(turn,degrees),"opening commit");ReverseDirectionVerification.Geometry(s.Faces);PetalFoldingVerification.Replay(s);Check(s.Undo()&&ReferenceEquals(faces,s.Faces),"opening undo");done=true;openings++;break;}if(done)break;}Check(done,"no opening for "+start+"/"+r);}
 Debug.Log("[ConnectedFold] PASS 8 rotated/swapped fragmented petals, "+poses+" sweep poses, backward scrub, fixed-layer blocking, partial/full replay and undo; "+openings+" continuous vertex-opening cases.");
 }
}}
